/**
 * Hand-maintained mirrors of `selfevals.api.schemas`.
 *
 * `types.gen.ts` (generated by `npm run gen:api` from the live OpenAPI
 * schema) is the source of truth for drift-checking — regenerate it and
 * diff when a backend schema changes. These hand types stay separate
 * because 30+ components already import named types from here and a
 * generated-types migration is a larger, separate change.
 */

export type WorkspaceSummary = {
  id: string;
  slug: string;
  name: string;
  description: string | null;
  owner_id: string | null;
  created_at: string;
  experiment_count: number;
  last_run_at: string | null;
};

export type WorkspaceDetail = WorkspaceSummary & {
  experiment_count: number;
  recent_health: number | null;
};

export type ExperimentSummary = {
  id: string;
  name: string;
  goal: string;
  mode: string;
  state: string;
  primary_metric: string;
  primary_target: { operator: string; value: number };
  proposer_strategy: string;
  max_iterations: number;
  created_at: string;
  updated_at: string;
  iteration_count: number;
};

export type IterationSummary = {
  id: string;
  iteration: number;
  state: string;
  hypothesis: string;
  proposed_parameters: Record<string, unknown>;
  primary_metric_name: string | null;
  primary_metric_value: number | null;
  delta_vs_best: number | null;
  decision_outcome: string | null;
  decision_rationale: string | null;
  cost_usd: number | null;
  duration_seconds: number | null;
  trace_run_ids: string[];
  created_at: string;
};

export type ExperimentDetail = {
  summary: ExperimentSummary;
  result: Record<string, unknown> | null;
  iterations: IterationSummary[];
};

export type ExperimentListPage = {
  items: ExperimentSummary[];
  total: number;
  limit: number;
  offset: number;
  has_more: boolean;
};

/** What the case declared it expected — only declared dimensions are present.
 * Mirror of `api.schemas.ExpectedView`. */
export type ExpectedView = {
  structured_output?: Record<string, unknown> | null;
  must_include?: string[] | null;
  must_not_include?: string[] | null;
  required_tools?: string[] | null;
  forbidden_tools?: string[] | null;
};

/** What the agent produced, projected to mirror `ExpectedView` for a direct
 * expected-vs-detected diff. Mirror of `api.schemas.DetectedView`. */
export type DetectedView = {
  content?: string | null;
  structured_output?: Record<string, unknown> | null;
  missing?: string[] | null;
  forbidden_present?: string[] | null;
  tools_invoked?: string[] | null;
};

/** One grader's verdict on a scenario, as it appears in
 * `ScenarioResult.grader_results[]`. `reason_pointer` is an `oss://` pointer to
 * the full reasoning when it was too large to inline; `breakdown` is the
 * grader's own nested detail (per-rule funnel, sub-scores). Kept loose on the
 * nested fields since their shape varies by grader type. */
export type GraderResult = {
  grader: string;
  label?: string | null;
  score?: number | null;
  reason?: string | null;
  reason_pointer?: string | null;
  confidence?: number | null;
  failure_modes?: string[] | null;
  breakdown?: Record<string, unknown> | null;
};

/** One evaluated scenario — a case, or one turn of a conversation case.
 * The single recursive shape behind `/results` and `/threads`. Mirror of
 * `api.schemas.ScenarioResult`. `expected`/`detected` are null when the case
 * declares nothing to compare; `matched`/`detected` are null with no trace. */
export type ScenarioResult = {
  case_id: string;
  case_name?: string | null;
  run_id?: string | null;
  trace_id?: string | null;
  iteration: number;
  position?: number | null;
  matched?: boolean | null;
  score?: number | null;
  label?: string | null;
  started_at?: string | null;
  message?: string | null;
  failure_modes: string[];
  expected?: ExpectedView | null;
  detected?: DetectedView | null;
  grader_results: GraderResult[];
  turns: ScenarioResult[];
};

export type ExperimentResults = {
  experiment_id: string;
  iteration: number | null;
  cases: ScenarioResult[];
  total: number;
};

export type FailureClusterExample = {
  run_id: string;
  experiment_id?: string | null;
};

/** One cluster = one failure mode (§J.6 v1). `status` is `"unknown"` for a mode
 * seen on a grade but not yet registered in the taxonomy. */
export type FailureClusterRow = {
  failure_mode: string;
  failure_mode_id?: string | null;
  title?: string | null;
  status: string;
  count: number;
  rate: number;
  examples: FailureClusterExample[];
};

export type FailureClusters = {
  workspace_id: string;
  window: { start: string | null; end: string | null };
  experiment_id: string | null;
  total: number;
  items: FailureClusterRow[];
};

export type DecisionRow = {
  id: string;
  iteration: number;
  outcome: string;
  automated_rationale: string;
  human_rationale: string | null;
  metrics_snapshot: Record<string, number>;
  created_at: string;
};

export type AnchorPoint = {
  experiment_id: string;
  experiment_name: string;
  iteration: number;
  primary_metric_name: string;
  primary_metric_value: number;
  decision_outcome: string;
  created_at: string;
};

export type SpanSummary = {
  id: string;
  parent_id: string | null;
  kind: string;
  name: string;
  started_at: string;
  duration_ms: number;
  detail: Record<string, unknown>;
};

export type TraceDetail = {
  id: string;
  run_id: string;
  experiment_id: string | null;
  experiment_name: string | null;
  iteration: number | null;
  thread_id: string | null;
  thread_position: number | null;
  final_state: string;
  started_at: string;
  ended_at: string | null;
  spans: SpanSummary[];
  metrics: Record<string, unknown>;
};

/** A conversation's turns, each a `ScenarioResult` — the same shape `/results`
 * uses (replaces the old flat `ThreadTurn`). Mirror of `api.schemas.ThreadResponse`. */
export type ThreadDetail = {
  thread_id: string;
  turn_count: number;
  turns: ScenarioResult[];
};

/**
 * One rolled-up funnel node (B2). Recursive: `children` is keyed by the
 * child node's `key`. Mirror of `selfevals.api.schemas.FunnelNodeResponse`.
 * The backend owns all the rollup math — the FE only renders this tree.
 */
export type FunnelNode = {
  key: string;
  count: number;
  mean_score: number | null;
  total_weight: number;
  label_counts: Record<string, number>;
  failure_mode_counts: Record<string, number>;
  children: Record<string, FunnelNode>;
};

export type FunnelDetail = {
  iteration_id: string;
  iteration: number;
  // Empty when no grader emitted a structured breakdown (the common case).
  nodes: Record<string, FunnelNode>;
};

// --- Compare (B3) -------------------------------------------------------
// Mirrors `selfevals.api.schemas.CompareResponse`. The server is the single
// source of truth for the diff math (the reporter's `compute_compare`); the
// FE renders this directly instead of recomputing deltas client-side.

export type CompareParamRow = {
  key: string;
  a: string;
  b: string;
  changed: boolean;
};

export type CompareMetricRow = {
  name: string;
  a: number | null;
  b: number | null;
  delta: number | null;
};

export type CompareFunnelRow = {
  path: string;
  a: number | null;
  b: number | null;
  delta: number | null;
};

export type CompareFailureModes = {
  only_a: Record<string, number>;
  only_b: Record<string, number>;
  common: Record<string, [number, number]>;
};

export type CompareRecommendation = {
  kind: 'winner' | 'tie' | 'different_metric' | 'none';
  winner: string | null;
  metric_name: string | null;
  a_metric_name: string | null;
  b_metric_name: string | null;
  a_value: number | null;
  b_value: number | null;
  delta: number | null;
  new_failure_modes: string[];
};

export type CompareResponse = {
  a_id: string;
  b_id: string;
  a_iteration: number;
  b_iteration: number;
  a_created_at: string;
  b_created_at: string;
  a_decision: string | null;
  b_decision: string | null;
  proposal_diff: CompareParamRow[];
  metrics_diff: CompareMetricRow[];
  failure_modes: CompareFailureModes;
  funnel_diff: CompareFunnelRow[];
  recommendation: CompareRecommendation;
  holdout_status: string;
};

// --- Metrics (observability layer) -------------------------------------
// Mirror of `selfevals.api.schemas.*MetricsResponse`. Every metrics endpoint
// shares the `{ workspace_id, window, experiment_id, total, items }` envelope;
// only the row shape differs. All take a `from`/`to` time-range (ISO strings).

export type MetricsWindow = { start: string | null; end: string | null };

type MetricsEnvelope<Row> = {
  workspace_id: string;
  window: MetricsWindow;
  experiment_id: string | null;
  total: number;
  items: Row[];
};

export type PassRateRow = { grader: string; label: string; count: number; rate: number };
export type FailureModeRow = { failure_mode: string; count: number; rate: number };
export type ToolRow = {
  tool_name: string;
  status: string;
  count: number;
  error_count: number;
  avg_duration_ms: number | null;
  retry_count: number;
};
export type CostRow = {
  provider: string;
  model: string;
  call_count: number;
  total_cost_usd: number;
  avg_cost_usd: number;
};
export type TokenRow = {
  provider: string;
  model: string;
  call_count: number;
  input_tokens: number;
  output_tokens: number;
  reasoning_tokens: number;
  total_tokens: number;
};
export type LatencyRow = {
  metric: string;
  count: number;
  p50_ms: number | null;
  p95_ms: number | null;
  p99_ms: number | null;
};

export type PassRateMetrics = MetricsEnvelope<PassRateRow>;
export type FailureModeMetrics = MetricsEnvelope<FailureModeRow>;
export type ToolMetrics = MetricsEnvelope<ToolRow>;
export type CostMetrics = MetricsEnvelope<CostRow>;
export type TokenMetrics = MetricsEnvelope<TokenRow>;
export type LatencyMetrics = MetricsEnvelope<LatencyRow>;

