// --- Error-analysis (loop-closer 2C) -----------------------------------
// Mirror of `analysis/schemas.py`. The bundle is the failed-traces + live
// taxonomy the human codes against; the result is what they compose back.

export type TaxonomyEntry = {
  id: string;
  slug: string;
  title: string;
  definition: string;
  status: string;
};

export type BundleGrade = {
  label: string;
  score: number | null;
  deterministic_modes: string[];
  judge_reason: string | null;
};

export type BundleMessage = { role: string; content: string };
export type BundleErrorSpan = { kind: string; name: string; error: string | null };

export type BundleTrace = {
  trace_id: string;
  run_id: string;
  thread_id: string | null;
  eval_case_id: string | null;
  grade: BundleGrade;
  transcript: BundleMessage[];
  first_error_span: BundleErrorSpan | null;
};

export type AnalysisBundle = {
  schema_version: string;
  workspace_id: string;
  experiment_id: string;
  iteration: number | null;
  taxonomy: TaxonomyEntry[];
  traces: BundleTrace[];
  instructions_ref: string;
};

// An assignment classifies a trace against an existing mode (`mode_id`) XOR
// proposes a new one (`new_mode_slug`). `proposed_modes` carries the new modes'
// definitions. This is what the annotation UI composes and POSTs.
export type AnalysisAssignment = {
  trace_id: string;
  mode_id?: string;
  new_mode_slug?: string;
  open_note?: string;
  quote?: string;
};

export type AnalysisProposedMode = {
  slug: string;
  title: string;
  definition: string;
  parent_slug?: string;
};

export type AnalysisResult = {
  assignments?: AnalysisAssignment[];
  proposed_modes?: AnalysisProposedMode[];
};

export type AnalysisIngestSummary = {
  assignments_applied: number;
  created_candidates: string[];
  updated_candidates: string[];
  hypotheses_recorded: number;
};

// --- Pairwise verdicts + tournaments -----------------------------------
// LLM + human pairwise judgments (RLHF / judge calibration) and N-candidate
// ranking via Elo / Bradley-Terry. Mirrors of `selfevals.api.schemas`.

/** One side of a compared pair. Mirror of `api.schemas.PairRefBody`. */
export type PairRef = {
  kind: string;
  trace_id?: string | null;
  case_id?: string | null;
  iteration_id?: string | null;
  content_snapshot?: string | null;
};

export type PairwiseVerdict = {
  id: string;
  a_ref: PairRef;
  b_ref: PairRef;
  preferred: 'a' | 'b' | 'tie';
  margin: number;
  rationale?: string | null;
  judge_kind: 'llm' | 'human';
  judge_id: string;
  rubric_version?: number | null;
  experiment_id?: string | null;
  case_id?: string | null;
  created_at: string;
};

/** A verdict to ingest. `id`/`workspace_id` are assigned server-side. */
export type IngestPairwiseVerdict = {
  a_ref: PairRef;
  b_ref: PairRef;
  preferred: 'a' | 'b' | 'tie';
  margin?: number;
  rationale?: string | null;
  judge_kind: 'llm' | 'human';
  judge_id: string;
  judge_model?: string | null;
  rubric_version?: number | null;
  position?: string | null;
  case_id?: string | null;
  dataset_id?: string | null;
};

export type PairwiseCalibrationCell = {
  rubric_version?: number | null;
  compared_pairs: number;
  agreements: number;
  disagreements: number;
  agreement_rate: number;
};

export type PairwiseCalibration = {
  compared_pairs: number;
  agreements: number;
  disagreements: number;
  agreement_rate: number;
  by_rubric_version: PairwiseCalibrationCell[];
};

export type TournamentCandidate = {
  id: string;
  output_text: string;
  trace_id?: string | null;
};

export type RunTournamentRequest = {
  candidates: TournamentCandidate[];
  /** Dotted path `mod:fn` to the LLM judge callable. */
  judge_entrypoint: string;
  rubric: string;
  strategy?: string;
  method?: string;
  baseline_id?: string | null;
  comparisons_per_candidate?: number;
  swiss_rounds?: number;
  swap_and_average?: boolean;
  case_input?: Record<string, unknown> | null;
};

export type RankingRow = {
  candidate_id: string;
  rank: number;
  score: number;
  wins: number;
  losses: number;
  ties: number;
  n_comparisons: number;
};

export type Tournament = {
  id: string;
  experiment_id?: string | null;
  strategy: string;
  method: string;
  candidate_ids: string[];
  baseline_id?: string | null;
  n_comparisons: number;
  swap_and_average: boolean;
  ranking: RankingRow[];
  created_at: string;
};

// --- Arena (code-variant bake-offs over git worktrees) --------------------
// Mirrors `selfevals.api.schemas` Arena* models + `arena.schemas.ArenaBundle`.

